=====================================

Here is a Python implementation of Kruskal's algorithm to find the Minimum Spanning Tree (MST) of a graph:

```python
class DisjointSet:
    def __init__(self, vertices):
        self.vertices = vertices
        self.parent = {v: v for v in vertices}
        self.rank = {v: 0 for v in vertices}

    def find(self, vertex):
        """Find the representative of a set."""
        if self.parent[vertex] != vertex:
            self.parent[vertex] = self.find(self.parent[vertex])
        return self.parent[vertex]

    def union(self, u, v):
        """Merge two sets into one."""
        root_u = self.find(u)
        root_v = self.find(v)

        if root_u != root_v:
            if self.rank[root_u] > self.rank[root_v]:
                self.parent[root_v] = root_u
            else:
                self.parent[root_u] = root_v
                if self.rank[root_u] == self.rank[root_v]:
                    self.rank[root_v] += 1


class Graph:
    def __init__(self, vertices):
        self.vertices = vertices
        self.edges = []

    def add_edge(self, u, v, weight):
        """Add an edge to the graph."""
        self.edges.append((u, v, weight))

    def kruskal_mst(self):
        """Find the Minimum Spanning Tree using Kruskal's algorithm."""
        mst_edges = []
        dsu = DisjointSet(self.vertices)

        # Sort edges in non-decreasing order of their weights
        self.edges.sort(key=lambda x: x[2])

        for u, v, weight in self.edges:
            if dsu.find(u) != dsu.find(v):
                mst_edges.append((u, v, weight))
                dsu.union(u, v)

        return mst_edges


# Example usage
g = Graph(5)
g.add_edge(0, 1, 2)
g.add_edge(0, 3, 6)
g.add_edge(1, 2, 3)
g.add_edge(1, 3, 8)
g.add_edge(1, 4, 5)
g.add_edge(2, 4, 7)
g.add_edge(3, 4, 9)

mst_edges = g.kruskal_mst()
for edge in mst_edges:
    print(f"Edge: {edge[0]} --{edge[1]}--, Weight: {edge[2]}")
```

